export type GraphNode = [id: string, type: string, label: string, scope: string, props: Record<string, string | number>];
export type GraphEdge = [src: string, dst: string, type: string, props?: Record<string, string | number>];
export interface Graph { nodes: GraphNode[]; edges: GraphEdge[] }

let cache: Promise<Graph> | null = null;
export function loadGraph() {
  cache ??= fetch("/ontology/graph.json").then((r) => r.json());
  return cache;
}

